def greedy_check(d, N):
    y = [0.0]
    for n in range(2, N + 1):
        candidates = [0.0]
        for m in range(1, n):
            candidates.append(y[m-1] + d/(n+m))

        candidates.sort()
        found = False
        for cand in candidates:
            if cand > 1.0 + 1e-11: # Allow for slight precision errors
                continue
            valid = True
            for m in range(1, n):
                if abs(cand - y[m-1]) < d/(n+m) - 1e-11:
                    valid = False
                    break
            if valid:
                y.append(cand)
                found = True
                break
        if not found:
            return False, y
    return True, y

for N in [10, 20, 50, 100, 200, 500, 1000]:
    low = 0.0
    high = 1.5
    for _ in range(20):
        mid = (low + high) / 2
        possible, _ = greedy_check(mid, N)
        if possible:
            low = mid
        else:
            high = mid
    print(f"N={N}, max_d_greedy={low}")
